import 'dart:async'; import '../models/chat_message.dart'; import 'contracts.dart';
class MockRealtimeService implements RealtimeService { final _events=StreamController<RealtimeEvent>.broadcast(); @override Stream<RealtimeEvent> get events=>_events.stream; void emit(RealtimeEvent event)=>_events.add(event); @override Future<void> connect()async{} @override Future<void> disconnect()async{} }
class MemoryLocalChatStorageService implements LocalChatStorageService { final _data=<String,List<ChatMessage>>{}; @override Future<List<ChatMessage>> readMessages(String id)async=>List.unmodifiable(_data[id]??[]); @override Future<void> saveMessages(String id,List<ChatMessage> messages)async{_data[id]=List.of(messages);} }
class MemoryOutboxService implements OutboxService { final _items=<ChatMessage>[]; @override Future<void> enqueue(ChatMessage m)async=>_items.add(m); @override Future<List<ChatMessage>> pending()async=>List.unmodifiable(_items); @override Future<void> remove(String id)async=>_items.removeWhere((m)=>m.id==id); }
class MockConnectivityService implements ConnectivityService { MockConnectivityService({this.online=true}); bool online; @override Stream<bool> get changes=>Stream.value(online); @override Future<bool> get isOnline async=>online; }
